class _FakeQuery:
    def __init__(self, rows, *, annotate_total_count=False):
        self._rows = rows
        self._offset = 0
        self._limit = None
        self._annotate_total_count = annotate_total_count

    def _clone(self, rows=None):
        clone = _FakeQuery(self._rows if rows is None else rows, annotate_total_count=self._annotate_total_count)
        clone._offset = self._offset
        clone._limit = self._limit
        return clone

    def filter(self, *args, **kwargs):
        del kwargs
        rows = list(self._rows)
        for criterion in args:
            left = getattr(criterion, "left", None)
            operator = getattr(criterion, "operator", None)
            right = getattr(criterion, "right", None)
            field_name = getattr(left, "name", None)
            if not field_name or operator is None:
                continue
            if operator is operators.eq:
                expected = getattr(right, "value", right)
                rows = [row for row in rows if getattr(row, field_name, None) == expected]
                continue
            if operator is operators.in_op:
                values = getattr(right, "value", right)
                if values is None:
                    continue
                allowed = set(values)
                rows = [row for row in rows if getattr(row, field_name, None) in allowed]
                continue
        return self._clone(rows)

    def order_by(self, *args, **kwargs):
        return self

    def group_by(self, *args, **kwargs):
        return self

    def join(self, *args, **kwargs):
        return self

    def distinct(self, *args, **kwargs):
        return self

    def options(self, *args, **kwargs):
        return self

    def add_columns(self, *args, **kwargs):
        del args, kwargs
        clone = self._clone()
        clone._annotate_total_count = True
        return clone

    def limit(self, *args, **kwargs):
        self._limit = args[0] if args else None
        del kwargs
        return self

    def offset(self, *args, **kwargs):
        self._offset = args[0] if args else 0
        del kwargs
        return self

    def count(self):
        return len(self._rows)

    def all(self):
        rows = list(self._rows)
        total = len(rows)
        if self._offset:
            rows = rows[self._offset :]
        if self._limit is not None:
            rows = rows[: self._limit]
        if self._annotate_total_count:
            return [(row, total) for row in rows]
        return rows

    def first(self):
        rows = self.all()
        return rows[0] if rows else None

    def scalar(self):
        row = self.first()
        if isinstance(row, (list, tuple)):
            return row[0] if row else None
        return row

    def delete(self, synchronize_session=False):
        count = len(self._rows)
        self._rows.clear()
        return count

    def update(self, values, synchronize_session=False):
        for row in self._rows:
            for key, value in (values or {}).items():
                name = getattr(key, "name", None)
                if name and hasattr(row, name):
                    setattr(row, name, value)
        return len(self._rows)


class _FakeDb:
    def __init__(self, rows=None):
        self.rows = rows or []
        self.added = []
        self.commits = 0

    def query(self, model=None, *args, **kwargs):
        del args, kwargs
        if model is None:
            return _FakeQuery(self.rows)
        model_name = getattr(model, "__name__", "")
        if not self.rows:
            return _FakeQuery([])
        first_name = getattr(self.rows[0].__class__, "__name__", "")
        if first_name == "_StageRun" and model_name == "BinarySecurityStageRun":
            return _FakeQuery(self.rows)
        return _FakeQuery(self.rows if not model_name or model_name == first_name else [])

    def add(self, obj):
        self.added.append(obj)

    def commit(self):
        self.commits += 1

    def flush(self):
        pass


class _NestedTransaction:
    def rollback(self):
        return None


class _ModelAwareDb:
    def __init__(
        self,
        *,
        tasks=None,
        stage_runs=None,
        stage_items=None,
        archive_jobs=None,
        events=None,
        state_events=None,
        state_leases=None,
        runtime_leases=None,
        operations=None,
        project_configs=None,
        service_configs=None,
        ea_tasks=None,
    ):
        self.tasks = list(tasks or [])
        self.stage_runs = list(stage_runs or [])
        self.stage_items = list(stage_items or [])
        self.archive_jobs = list(archive_jobs or [])
        self.events = list(events or [])
        self.sync_events = []
        self.state_events = list(state_events or [])
        self.state_leases = list(state_leases or [])
        self.runtime_leases = list(runtime_leases or [])
        self.operations = list(operations or [])
        self.project_configs = list(project_configs or [])
        self.service_configs = list(service_configs or [])
        self.ea_tasks = list(ea_tasks or [])
        self.added = []
        self.queried_models = []

    def query(self, model, *args, **kwargs):
        model_name = getattr(model, "__name__", "")
        self.queried_models.append(model_name)
        if model_name == "BinarySecurityTask":
            return _FakeQuery(self.tasks)
        if model_name == "BinarySecurityStageRun":
            return _FakeQuery(self.stage_runs)
        if model_name == "BinarySecurityStageItem":
            return _FakeQuery(self.stage_items)
        if model_name == "BinarySecurityArchiveJob":
            return _FakeQuery(self.archive_jobs)
        if model_name == "BinarySecurityEvent":
            return _FakeQuery(self.events)
        if model_name == "BinarySecuritySyncEvent":
            return _FakeQuery(self.sync_events)
        if model_name == "BinarySecurityStateEvent":
            return _FakeQuery(self.state_events)
        if model_name == "BinarySecurityTaskStateLease":
            return _FakeQuery(self.state_leases)
        if model_name == "BinarySecurityTaskRuntimeLease":
            return _FakeQuery(self.runtime_leases)
        if model_name == "BinarySecurityTaskOperation":
            return _FakeQuery(self.operations)
        if model_name == "BinarySecurityProjectConfig":
            return _FakeQuery(self.project_configs)
        if model_name == "BinarySecurityServiceConfig":
            return _FakeQuery(self.service_configs)
        return _FakeQuery([])

    def add(self, obj):
        self.added.append(obj)
        model_name = obj.__class__.__name__
        if model_name == "BinarySecurityEvent":
            self.events.append(obj)
        elif model_name == "BinarySecuritySyncEvent":
            self.sync_events.append(obj)
        elif model_name == "BinarySecurityStateEvent":
            self.state_events.append(obj)
        elif model_name == "BinarySecurityArchiveJob":
            self.archive_jobs.append(obj)
        elif model_name == "BinarySecurityStageItem":
            self.stage_items.append(obj)
        elif model_name == "BinarySecurityStageRun":
            self.stage_runs.append(obj)
        elif model_name == "BinarySecurityTask":
            self.tasks.append(obj)
        elif model_name == "BinarySecurityTaskRuntimeLease":
            self.runtime_leases.append(obj)

    def delete(self, obj):
        for rows in (
            self.tasks,
            self.stage_runs,
            self.stage_items,
            self.archive_jobs,
            self.events,
            self.sync_events,
            self.state_events,
            self.state_leases,
            self.runtime_leases,
            self.operations,
            self.project_configs,
            self.service_configs,
        ):
            if obj in rows:
                rows.remove(obj)
                break

    def commit(self):
        pass

    def flush(self):
        pass

    def rollback(self):
        return None

    def close(self):
        return None

    def begin_nested(self):
        return _NestedTransaction()


class _FakeTaskSyncQueue:
    def __init__(self):
        self.entries_by_task: dict[str, list[dict[str, object]]] = {}
        self.repair_locks: dict[str, str] = {}
        self.owner_signals: dict[tuple[str, str], dict[str, object]] = {}

    @staticmethod
    def _dedupe_key(entry: dict[str, object], fallback: str | None = None) -> str:
        value = str(entry.get("dedupe_key") or fallback or "").strip()
        if value:
            return value
        return "missing"

    async def enqueue_task_sync_request(self, task_id: str, entry: dict[str, object], *, dedupe_key: str, context: str = "test"):
        del context
        task_entries = self.entries_by_task.setdefault(str(task_id), [])
        resolved_dedupe_key = self._dedupe_key(entry, dedupe_key)
        for current in task_entries:
            if self._dedupe_key(current) != resolved_dedupe_key:
                continue
            current["item_ids"] = sorted(
                {
                    *[str(value).strip() for value in list(current.get("item_ids") or []) if str(value).strip()],
                    *[str(value).strip() for value in list(entry.get("item_ids") or []) if str(value).strip()],
                }
            )
            current["archive_job_ids"] = sorted(
                {
                    *[str(value).strip() for value in list(current.get("archive_job_ids") or []) if str(value).strip()],
                    *[str(value).strip() for value in list(entry.get("archive_job_ids") or []) if str(value).strip()],
                }
            )
            current["force"] = bool(current.get("force") or entry.get("force"))
            current["last_requested_at"] = entry.get("last_requested_at") or current.get("last_requested_at")
            current["payload"] = {**dict(current.get("payload") or {}), **dict(entry.get("payload") or {})}
            return dict(current)
        normalized = dict(entry)
        normalized["dedupe_key"] = resolved_dedupe_key
        normalized["queue_item_id"] = str(entry.get("queue_item_id") or f"tsq_{len(task_entries) + 1}")
        task_entries.append(normalized)
        return dict(normalized)

    async def pop_task_sync_request(self, task_id: str, *, now_epoch: float | None = None, context: str = "test"):
        del now_epoch, context
        task_entries = self.entries_by_task.get(str(task_id), [])
        if not task_entries:
            return None
        return dict(task_entries[0])

    async def ack_task_sync_request(self, task_id: str, *, queue_item_id: str, dedupe_key: str | None = None, context: str = "test"):
        del context
        task_entries = self.entries_by_task.get(str(task_id), [])
        remaining = []
        for current in task_entries:
            if str(current.get("queue_item_id") or "").strip() == str(queue_item_id or "").strip():
                continue
            if dedupe_key and self._dedupe_key(current) == str(dedupe_key or "").strip():
                continue
            remaining.append(current)
        self.entries_by_task[str(task_id)] = remaining

    async def retry_task_sync_request(self, task_id: str, entry: dict[str, object], *, context: str = "test"):
        del context
        task_entries = self.entries_by_task.setdefault(str(task_id), [])
        queue_item_id = str(entry.get("queue_item_id") or "").strip()
        for index, current in enumerate(task_entries):
            if str(current.get("queue_item_id") or "").strip() == queue_item_id:
                task_entries[index] = dict(entry)
                return dict(entry)
        task_entries.append(dict(entry))
        return dict(entry)

    async def list_task_sync_requests(self, task_id: str, *, context: str = "test"):
        del context
        return [dict(entry) for entry in list(self.entries_by_task.get(str(task_id), []))]

    async def has_due_task_sync_request(self, task_id: str, *, now_epoch: float | None = None, context: str = "test"):
        del context
        task_entries = self.entries_by_task.get(str(task_id), [])
        if not task_entries:
            return False
        threshold = float(now_epoch if now_epoch is not None else time.time())
        for entry in task_entries:
            next_retry_at = str(entry.get("next_retry_at") or "").strip()
            if not next_retry_at:
                return True
            try:
                due_at = datetime.fromisoformat(next_retry_at).timestamp()
            except ValueError:
                return True
            if due_at <= threshold:
                return True
        return False

    async def push_owner_signal(self, owner_instance_id: str, task_id: str, *, context: str = "test"):
        self.owner_signals[(str(owner_instance_id), str(task_id))] = {
            "owner_instance_id": str(owner_instance_id),
            "task_id": str(task_id),
            "context": context,
        }

    async def consume_owner_signal(self, owner_instance_id: str, task_id: str, *, context: str = "test"):
        del context
        return self.owner_signals.pop((str(owner_instance_id), str(task_id)), None)

    async def acquire_task_sync_repair_lock(self, task_id: str, owner_token: str, *, ttl_seconds: int = 30, context: str = "test"):
        del ttl_seconds, context
        task_id = str(task_id)
        if task_id in self.repair_locks:
            return False
        self.repair_locks[task_id] = str(owner_token)
        return True

    async def release_task_sync_repair_lock(self, task_id: str, owner_token: str, *, context: str = "test"):
        del context
        task_id = str(task_id)
        if self.repair_locks.get(task_id) == str(owner_token):
            self.repair_locks.pop(task_id, None)

    def refresh(self, obj):
        return obj

    def expire_all(self):
        return None

    def rollback(self):
        pass

    def close(self):
        pass

    def delete(self, obj):
        if obj in self.events:
            self.events.remove(obj)
        if obj in self.sync_events:
            self.sync_events.remove(obj)
        if obj in self.state_events:
            self.state_events.remove(obj)
        if obj in self.runtime_leases:
            self.runtime_leases.remove(obj)
        if obj in self.archive_jobs:
            self.archive_jobs.remove(obj)
        if obj in self.stage_items:
            self.stage_items.remove(obj)
        if obj in self.stage_runs:
            self.stage_runs.remove(obj)
        if obj in self.tasks:
            self.tasks.remove(obj)


class StatusMappingTests(unittest.TestCase):
    def test_map_downstream_status_treats_completed_limited_as_success(self):
        manager = TaskManager()
        self.assertEqual("success", manager._map_downstream_status("completed_limited"))

    def test_status_from_downstream_payload_treats_completed_limited_as_success(self):
        manager = TaskManager()
        self.assertEqual(
            "success",
            manager._status_from_downstream_payload({"status": "completed_limited"}, success_statuses={"passed", "success"}),
        )

    def test_status_from_downstream_payload_preserves_non_terminal_pending_statuses(self):
        manager = TaskManager()
        self.assertEqual(
            manager._status_from_downstream_payload({"status": "pending"}, success_statuses={"passed", "success"}),
            "pending",
        )
        self.assertEqual(
            manager._status_from_downstream_payload({"status": "queued"}, success_statuses={"passed", "success"}),
            "pending",
        )
        self.assertEqual(
            manager._status_from_downstream_payload({"status": "running"}, success_statuses={"passed", "success"}),
            "running",
        )


class ArchiveReclaimTests(unittest.TestCase):
    def setUp(self):
        self.manager = TaskManager()
        self.manager.instance_id = "worker-a"
        self.manager.cfg.scheduler.archive_reclaim_timeout_seconds = 300
        self.manager.cfg.scheduler.archive_reclaim_max_attempts = 3
        self.manager.cfg.scheduler.archive_copy_missing_source_retry_schedule_seconds = [60, 120, 180]

    def _task(self):
        return BinarySecurityTask(
            id="task-1",
            project_id="project-1",
            name="task",
            task_type=TASK_TYPE_BINARY_MODULE,
            status="running",
            current_stage="dataflow_vuln_scan",
            workspace_root="/tmp/task-1",
            created_at=_now(),
            updated_at=_now(),
        )

    def _stage_run(self, *, status="running"):
        return BinarySecurityStageRun(
            id="sr-1",
            task_id="task-1",
            project_id="project-1",
            stage_name="dataflow_vuln_scan",
            sequence_no=1,
            status=status,
            created_at=_now(),
            updated_at=_now(),
        )

    def _item(self, *, status="success"):
        return BinarySecurityStageItem(
            id="item-1",
            task_id="task-1",
            project_id="project-1",
            stage_run_id="sr-1",
            stage_name="dataflow_vuln_scan",
            item_key="entry-1",
            item_identity_key="entry-1::parent",
            parent_key="parent",
            downstream_service="dataflow_vuln_scan",
            downstream_task_id="dfa-1",
            status=status,
            created_at=_now(),
            updated_at=_now(),
        )

    def _archive_job(self, *, status="running", attempts=1, started_delta_seconds=600):
        now = _now()
        started_at = now - timedelta(seconds=started_delta_seconds)
        return BinarySecurityArchiveJob(
            id="aj-1",
            task_id="task-1",
            project_id="project-1",
            stage_name="dataflow_vuln_scan",
            item_id="item-1",
            item_key="entry-1",
            downstream_service="dataflow_vuln_scan",
            downstream_task_id="dfa-1",
            archive_status=status,
            owner_id=None,
            attempts=attempts,
            created_at=started_at,
            started_at=started_at,
            updated_at=started_at,
        )

    def test_reclaim_stale_running_archive_job_requeues_pending(self):
        task = self._task()
        stage_run = self._stage_run()
        item = self._item()
        job = self._archive_job()
        db = _ModelAwareDb(tasks=[task], stage_runs=[stage_run], stage_items=[item], archive_jobs=[job])
        with patch("app.service.task_manager.get_session_factory", return_value=lambda: db):
            reclaimed = self.manager._reclaim_stale_archive_jobs()
        self.assertEqual(reclaimed, 1)
        self.assertEqual(job.archive_status, "pending")
        self.assertIsNone(job.started_at)
        self.assertIsNone(job.completed_at)
        self.assertIsNone(job.archive_root)

    def test_reclaim_stale_running_archive_job_exhausted_marks_failed(self):
        task = self._task()
        stage_run = self._stage_run()
        item = self._item()
        job = self._archive_job(attempts=4)
        db = _ModelAwareDb(tasks=[task], stage_runs=[stage_run], stage_items=[item], archive_jobs=[job])
        with patch("app.service.task_manager.get_session_factory", return_value=lambda: db):
            reclaimed = self.manager._reclaim_stale_archive_jobs()
        self.assertEqual(reclaimed, 1)
        self.assertEqual(job.archive_status, "failed")
        self.assertIn("reclaim exhausted", str(job.error_message))

    def test_reclaim_stale_running_archive_job_defers_to_owner_when_task_lease_active(self):
        task = self._task()
        task.dispatcher_instance_id = "worker-owner"
        task.lease_expires_at = _now() + timedelta(minutes=5)
        runtime_lease = BinarySecurityTaskRuntimeLease(
            task_id=task.id,
            owner_instance_id="worker-owner",
            heartbeat_at=_now(),
            lease_expires_at=_now() + timedelta(minutes=5),
        )
        stage_run = self._stage_run()
        item = self._item()
        job = self._archive_job()
        db = _ModelAwareDb(
            tasks=[task],
            stage_runs=[stage_run],
            stage_items=[item],
            archive_jobs=[job],
            runtime_leases=[runtime_lease],
            events=[],
        )
        queued: list[str] = []
        owner_signals: list[tuple[str, str]] = []
        original_enqueue = self.manager._enqueue_task
        original_enqueue_owner_signal = self.manager._enqueue_owner_signal
        try:
            self.manager._enqueue_task = lambda task_id, *_args, **_kwargs: queued.append(task_id)
            self.manager._enqueue_owner_signal = (
                lambda owner_instance_id, task_id, **_kwargs: owner_signals.append((owner_instance_id, task_id))
            )
            with patch("app.service.task_manager.get_session_factory", return_value=lambda: db):
                reclaimed = self.manager._reclaim_stale_archive_jobs()
        finally:
            self.manager._enqueue_task = original_enqueue
            self.manager._enqueue_owner_signal = original_enqueue_owner_signal
        self.assertEqual(reclaimed, 1)
        self.assertEqual("failed", job.archive_status)
        self.assertIn("delegated to task owner repair", str(job.error_message))
        workset = dict((task.summary or {}).get("runtime_workset") or {})
        self.assertEqual("dataflow_vuln_scan", workset["pending_archive_rebuild"]["stage_name"])
        self.assertEqual("failed_items", workset["pending_archive_rebuild"]["rebuild_mode"])
        self.assertEqual([], queued)
        self.assertEqual([], owner_signals)
        event_types = [event.event_type for event in db.events]
        self.assertIn("downstream_archive_rebuild_deferred_to_owner", event_types)
        self.assertNotIn("owner_reconcile_signal_enqueued", event_types)

    def test_stop_cleanup_requeues_owned_running_archive_jobs(self):
        task = self._task()
        stage_run = self._stage_run()
        item = self._item()
        job = self._archive_job()
        job.owner_id = "worker-a"
        db = _ModelAwareDb(tasks=[task], stage_runs=[stage_run], stage_items=[item], archive_jobs=[job])
        with patch("app.service.task_manager.get_session_factory", return_value=lambda: db):
            reclaimed = self.manager._requeue_owned_running_archive_jobs()
        self.assertEqual(reclaimed, 1)
        self.assertEqual(job.archive_status, "pending")

    def test_stage_success_blocked_when_archive_not_finished(self):
        task = self._task()
        upstream_run = BinarySecurityStageRun(
            id="sr-upstream",
            task_id="task-1",
            project_id="project-1",
            stage_name="binary_to_source",
            sequence_no=1,
            status="success",
            created_at=_now(),
            updated_at=_now(),
        )
        entry_run = BinarySecurityStageRun(
            id="sr-entry",
            task_id="task-1",
            project_id="project-1",
            stage_name="entry_analysis",
            sequence_no=2,
            status="success",
            created_at=_now(),
            updated_at=_now(),
        )
        stage_run = self._stage_run(status="success")
        stage_run.sequence_no = 3
        item = self._item(status="success")
        job = self._archive_job(status="running")
        db = _ModelAwareDb(tasks=[task], stage_runs=[upstream_run, entry_run, stage_run], stage_items=[item], archive_jobs=[job])
        with patch("app.service.task_manager.get_session_factory", return_value=lambda: db):
            blocked = self.manager._stage_archive_success_blocked(task, "dataflow_vuln_scan", [item])
            status = self.manager._business_stage_status(task, "dataflow_vuln_scan", stage_run, [item])
            next_stage = self.manager._next_incomplete_stage(db, task)
        self.assertFalse(blocked)
        self.assertEqual(status, "success")
