    def test_repair_retryable_state_events_skips_lock_busy_and_terminal_tasks(self):
        active_task = BinarySecurityTask(
            id="t-active",
            project_id="p1",
            name="active",
            status="running",
            created_at=_now(),
            updated_at=_now(),
        )
        terminal_task = BinarySecurityTask(
            id="t-terminal",
            project_id="p1",
            name="terminal",
            status="failed",
            created_at=_now(),
            updated_at=_now(),
        )
        lock_busy_event = BinarySecurityStateEvent(
            id="se-lock-busy",
            task_id="t-active",
            project_id="p1",
            stage_name="dataflow_vuln_scan",
            event_type="downstream_status_observed",
            status="retryable",
            attempts=3,
            processing_result="lock_busy_backoff",
            last_error_message="task state lease busy",
            available_at=_now(),
            created_at=_now(),
            updated_at=_now(),
        )
        terminal_retryable_event = BinarySecurityStateEvent(
            id="se-terminal",
            task_id="t-terminal",
            project_id="p1",
            stage_name="dataflow_vuln_scan",
            event_type="downstream_status_observed",
            status="retryable",
            attempts=2,
            processing_result="retryable",
            last_error_message="downstream timeout",
            available_at=_now(),
            created_at=_now(),
            updated_at=_now(),
        )
        real_retryable_event = BinarySecurityStateEvent(
            id="se-real",
            task_id="t-active",
            project_id="p1",
            stage_name="dataflow_vuln_scan",
            event_type="downstream_status_observed",
            status="retryable",
            attempts=2,
            processing_result="retryable",
            last_error_message="downstream timeout",
            available_at=_now(),
            created_at=_now(),
            updated_at=_now(),
        )
        db = _AppendingModelAwareDb(
            tasks=[active_task, terminal_task],
            state_events=[lock_busy_event, terminal_retryable_event, real_retryable_event],
            events=[],
        )

        queued_tasks = []
        original_enqueue = self.manager._enqueue_task_with_context
        self.manager._enqueue_task_with_context = lambda task_id, **_kwargs: queued_tasks.append(task_id)
        try:
            repaired = self.manager._repair_retryable_state_events(db)
        finally:
            self.manager._enqueue_task_with_context = original_enqueue

        self.assertEqual(1, repaired)
        self.assertEqual("retryable", lock_busy_event.status)
        self.assertEqual("lock_busy_backoff", lock_busy_event.processing_result)
        self.assertEqual("retryable", terminal_retryable_event.status)
        self.assertEqual("processed", real_retryable_event.status)
        self.assertEqual("owner_signal_requeued", real_retryable_event.processing_result)
        self.assertIn("pending_task_layer_reconcile", ((active_task.summary or {}).get("runtime_workset") or {}))
        self.assertEqual(
            1,
            len({id(event) for event in db.events if event.event_type == "task_state_repair_reconcile_triggered"}),
        )
        self.assertEqual(["t-active"], queued_tasks)
        self.assertEqual(
            1,
            len({id(event) for event in db.events if event.event_type == "owned_execution_owner_reconcile_requested"}),
        )
        self.assertEqual(
            1,
            len({id(event) for event in db.events if event.event_type == "shared_dispatch_signal_enqueued"}),
        )

    def test_build_project_stats_sql_aggregates_counts_from_database(self):
        task1 = BinarySecurityTask(
            id="t1",
            project_id="p1",
            name="a",
            status="running",
            task_type=TASK_TYPE_BINARY,
            firmware_source="project_filesystem",
            firmware_path="/fw/a",
            output_root="/o",
            workspace_root="/w/a",
        )
        task1.metrics = {
            "selected_module_count": 2,
            "candidate_module_count": 3,
            "high_risk_module_count": 1,
            "entry_count": 4,
            "vuln_result_count": 5,
            "firmware_item_count": 6,
            "unpacked_firmware_count": 1,
            "failed_firmware_count": 0,
        }
        task2 = BinarySecurityTask(
            id="t2",
            project_id="p1",
            name="b",
            status="success",
            task_type=TASK_TYPE_SOURCE,
            firmware_source="project_filesystem",
            firmware_path="/fw/b",
            output_root="/o",
            workspace_root="/w/b",
        )
        task2.metrics = {
            "selected_module_count": 7,
            "candidate_module_count": 8,
            "high_risk_module_count": 2,
            "entry_count": 9,
            "vuln_result_count": 10,
            "firmware_item_count": 11,
            "unpacked_firmware_count": 0,
            "failed_firmware_count": 0,
        }

        engine = create_engine("sqlite:///:memory:")
        BinarySecurityTask.__table__.create(bind=engine)
        SessionLocal = sessionmaker(bind=engine)
        session = SessionLocal()
        try:
            session.add(task1)
            session.add(task2)
            session.commit()

            stats = self.manager._build_project_stats_sql(session, project_id="p1", task_type=None)

            self.assertEqual(2, stats.total)
            self.assertEqual(1, stats.running)
            self.assertEqual(1, stats.success)
            self.assertEqual(9, stats.selected_module_count)
            self.assertEqual(11, stats.candidate_module_count)
            self.assertEqual(3, stats.high_risk_module_count)
            self.assertEqual(13, stats.entry_count)
            self.assertEqual(15, stats.vuln_result_count)
            self.assertEqual(17, stats.input_count)
        finally:
            session.close()

