        id="syncevt-1",
        project_id="p1",
        task_id=task.id,
        stage_name="entry_analysis",
        item_id="item-1",
        item_key="entry-1",
        item_name="EntryOne",
        downstream_service="entry_analyse",
        downstream_task_id="ea-1",
        operation="downstream_sync",
        event_type="applied",
        sync_status="synced",
        outcome="success",
